const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const overlayVendors = d.overlayDetection?.overlayVendors || [];
  const hasOverlay = Boolean(d.overlayDetection?.overlayDetected);
  const missingStatement = d.eaaCompliance?.accessibilityStatementFound === false;
  const topIssue = Array.isArray(d.topViolations) && d.topViolations.length > 0 ? d.topViolations[0] : null;

  let campaignAngle = 'ADA_WCAG_REMEDIATION';
  let subjectLine = `Quick WCAG 2.2 accessibility note on ${new URL(d.finalUrl || d.url).hostname}`;

  if (hasOverlay) {
    campaignAngle = 'OVERLAY_REPLACEMENT';
    subjectLine = `${overlayVendors[0] || 'Accessibility'} widget on ${new URL(d.finalUrl || d.url).hostname} (+ ${d.summary?.totalViolations || 'several'} open DOM issues)`;
  } else if (missingStatement) {
    campaignAngle = 'EAA_MISSING_STATEMENT';
    subjectLine = `EAA accessibility statement + WCAG 2.2 check on ${new URL(d.finalUrl || d.url).hostname}`;
  }

  const emailDraft = [
    `Hi team,`,
    ``,
    d.salesPitchHook || `Ran a quick automated WCAG 2.2 AA check on ${d.url} and spotted ${d.summary?.totalViolations || 0} technical accessibility issues (Risk Score: ${d.legalRiskScore}/100).`,
    topIssue
      ? `For example, rule "${topIssue.ruleId}" (${topIssue.impact}) affects ${topIssue.affectedNodesCount} element(s) on your page and can be fixed directly in HTML/ARIA:`
      : ``,
    topIssue?.suggestedFixHtml ? `Suggested fix snippet:\n${topIssue.suggestedFixHtml}` : ``,
    d.visualEvidenceUrl ? `Annotated screenshot showing the exact elements: ${d.visualEvidenceUrl}` : ``,
    ``,
    `Would it be helpful if I sent over the full technical remediation checklist so your dev team can patch these in under an hour?`,
    ``,
    `Best,`,
    `[Your Name]`,
    `---`,
    `Note: ${d.disclaimer || 'Automated technical WCAG 2.2 check for informational purposes only; not legal advice.'}`
  ].filter(Boolean).join('\n');

  results.push({
    json: {
      prospectUrl: d.url,
      finalUrl: d.finalUrl,
      auditedAt: d.auditedAt,
      legalRiskScore: d.legalRiskScore,
      riskTier: d.riskTier,
      campaignAngle,
      subjectLine,
      salesPitchHook: d.salesPitchHook,
      overlayDetected: hasOverlay,
      overlayVendors: overlayVendors.join(', '),
      accessibilityStatementFound: d.eaaCompliance?.accessibilityStatementFound ?? null,
      totalViolations: d.summary?.totalViolations ?? 0,
      criticalViolations: d.summary?.criticalCount ?? 0,
      seriousViolations: d.summary?.seriousCount ?? 0,
      topViolationRuleId: topIssue?.ruleId ?? null,
      beforeHtml: topIssue?.beforeHtml ?? null,
      suggestedFixHtml: topIssue?.suggestedFixHtml ?? null,
      visualEvidenceUrl: d.visualEvidenceUrl ?? null,
      coldOutreachEmailBody: emailDraft,
      disclaimer: d.disclaimer
    }
  });
}

return results;
